void near DoDefendNest(int ant)
{
    int scent;

    if (Dx8[ant + 0x2f62] & 0x80)
        scent = Dx8[((Dx8[ant + 0x23a4] & 0xfe) << 4) +
                    (Dx8[ant + 0x278e] >> 1) + 0x72d2];
    else
        scent = Dx8[((Dx8[ant + 0x23a4] & 0xfe) << 4) +
                    (Dx8[ant + 0x278e] >> 1) + 0x62d2];
    if (scent < 0x6e)
        DoToNestAnt(ant);
    else
        DoRandAntAA(ant);
}
